INSERT INTO `broadcast_templates` (`id`, `user_id`, `title`, `message`, `image_url`, `created_at`, `updated_at`) VALUES
(1, NULL, 'Follow Up Repeat Order (Jadwal Beli Kembali)', 'Halo Kak {nama}! Terima kasih telah setia bersama Gadgetmart. Berdasarkan riwayat belanja, kemungkinan saatnya Kakak memperbarui kebutuhan seputar {item}. Dapatkan promo tukar tambah menarik & garansi resmi hanya di Gadgetmart. Balas pesan ini untuk info promo hari ini ya! 📱✨', NULL, '2026-11-03 07:32:18', '2026-11-03 07:32:18'),
(2, NULL, 'Promo Khusus Aksesoris & Proteksi (ACC)', 'Halo Kak {nama}, gimana kabar gadget-nya? Supaya perangkat Kakak selalu terlindungi, Gadgetmart ada promo diskon spesial untuk tempered glass, case original, adaptor fast charging, & audio. Yuk mampir ke toko atau balas pesan ini untuk pilihan katalognya! 🎧⚡', NULL, '2026-11-03 07:32:19', '2026-11-03 07:32:19'),
(3, NULL, 'Greeting & Cek Kepuasan Konsumen', 'Halo Kak {nama}, salam hangat dari tim Gadgetmart! Kami ingin memastikan apakah perangkat atau belanjaan Kakak berfungsi dengan nyaman. Jika ada pertanyaan, servis, atau kebutuhan aksesoris, tim kami siap membantu sepenuh hati. Have a wonderful day! 😊🙌', NULL, '2026-11-03 07:32:20', '2026-11-03 07:32:20'),
(4, NULL, 'Voucher Eksklusif Pelanggan Setia (VIP)', 'Spesial untuk Kak {nama}! Sebagai apresiasi pelanggan setia Gadgetmart, kami siapkan voucher cashback belanja untuk transaksi berikutnya. Tunjukkan pesan WhatsApp resmi ini ke kasir store Gadgetmart terdekat untuk klaim keuntungannya ya Kak! 🎁🛍️', NULL, '2026-11-03 07:32:21', '2026-11-03 07:32:21');

